CREATE TABLE public.site_content (key text PRIMARY KEY, text_ar text NOT NULL DEFAULT '', text_en text NOT NULL DEFAULT '', image_url text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_content TO anon, authenticated; GRANT ALL ON public.site_content TO service_role; GRANT INSERT, UPDATE, DELETE ON public.site_content TO authenticated;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public content read" ON public.site_content FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Active admins manage content" ON public.site_content FOR ALL TO authenticated USING(public.is_account_active() AND public.has_role(auth.uid(),'admin')) WITH CHECK(public.is_account_active() AND public.has_role(auth.uid(),'admin'));
ALTER TABLE public.products ADD COLUMN stock_quantity integer, ADD COLUMN low_stock_threshold integer NOT NULL DEFAULT 3;
ALTER TABLE public.products ADD CONSTRAINT products_stock_nonnegative CHECK(stock_quantity IS NULL OR stock_quantity>=0), ADD CONSTRAINT products_threshold_nonnegative CHECK(low_stock_threshold>=0);
ALTER TABLE public.order_events ADD COLUMN changes jsonb NOT NULL DEFAULT '{}'::jsonb;
DROP POLICY "Admins read order history" ON public.order_events;
CREATE POLICY "Owner or admin order history" ON public.order_events FOR SELECT TO authenticated USING(public.is_account_active() AND EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id AND (o.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE OR REPLACE FUNCTION public.record_order_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.updated_at=now(); INSERT INTO public.order_events(order_id,actor_id,status,note,changes) VALUES(NEW.id,auth.uid(),NEW.status,CASE WHEN OLD.archived IS DISTINCT FROM NEW.archived THEN 'Archive state changed' WHEN OLD.delivery_address IS DISTINCT FROM NEW.delivery_address OR OLD.customer_name IS DISTINCT FROM NEW.customer_name OR OLD.customer_phone IS DISTINCT FROM NEW.customer_phone THEN 'Customer delivery details corrected' ELSE NEW.admin_notes END,jsonb_build_object('before',jsonb_build_object('status',OLD.status,'archived',OLD.archived,'customer_name',OLD.customer_name,'customer_phone',OLD.customer_phone,'delivery_address',OLD.delivery_address),'after',jsonb_build_object('status',NEW.status,'archived',NEW.archived,'customer_name',NEW.customer_name,'customer_phone',NEW.customer_phone,'delivery_address',NEW.delivery_address))); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.checkout_cart(_name text,_phone text,_address text,_notes text,_request_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; amount numeric; BEGIN
IF NOT public.is_account_active() THEN RAISE EXCEPTION 'Unauthorized'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text));
SELECT id INTO oid FROM public.orders WHERE id=_request_id AND user_id=auth.uid(); IF oid IS NOT NULL THEN RETURN oid; END IF;
IF _name IS NULL OR _phone IS NULL OR _address IS NULL OR _notes IS NULL OR length(trim(_name))<2 OR length(trim(_phone))<7 OR length(trim(_address))<3 OR length(_name)>150 OR length(_phone)>40 OR length(_address)>1000 OR length(_notes)>2000 THEN RAISE EXCEPTION 'Invalid delivery details'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.cart_items WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Cart is empty'; END IF;
PERFORM p.id FROM public.products p WHERE p.id IN(SELECT product_id FROM public.cart_items WHERE user_id=auth.uid()) ORDER BY p.id FOR UPDATE;
IF EXISTS(SELECT 1 FROM public.cart_items c LEFT JOIN public.products p ON p.id=c.product_id WHERE c.user_id=auth.uid() AND (p.id IS NULL OR NOT p.is_active OR p.price<0 OR c.quantity<1 OR c.quantity>999 OR (cardinality(p.sizes)>0 AND (c.size IS NULL OR NOT c.size=ANY(p.sizes))))) THEN RAISE EXCEPTION 'Cart contains unavailable products, sizes or invalid quantities'; END IF;
IF EXISTS(SELECT 1 FROM public.products p JOIN(SELECT product_id,sum(quantity) qty FROM public.cart_items WHERE user_id=auth.uid() GROUP BY product_id) c ON c.product_id=p.id WHERE p.stock_quantity IS NOT NULL AND p.stock_quantity<c.qty) THEN RAISE EXCEPTION 'Insufficient stock'; END IF;
SELECT sum(p.price*c.quantity) INTO amount FROM public.cart_items c JOIN public.products p ON p.id=c.product_id WHERE c.user_id=auth.uid();
INSERT INTO public.orders(id,user_id,customer_name,customer_phone,delivery_address,customer_notes,total) VALUES(_request_id,auth.uid(),trim(_name),trim(_phone),trim(_address),_notes,amount) RETURNING id INTO oid;
INSERT INTO public.order_items(order_id,product_id,name_ar,name_en,size,quantity,unit_price,image_url) SELECT oid,p.id,p.name_ar,p.name_en,c.size,c.quantity,p.price,p.image_url FROM public.cart_items c JOIN public.products p ON p.id=c.product_id WHERE c.user_id=auth.uid();
UPDATE public.products p SET stock_quantity=p.stock_quantity-c.qty FROM(SELECT product_id,sum(quantity)::integer qty FROM public.cart_items WHERE user_id=auth.uid() GROUP BY product_id) c WHERE p.id=c.product_id AND p.stock_quantity IS NOT NULL;
INSERT INTO public.order_events(order_id,actor_id,status) VALUES(oid,auth.uid(),'pending'); DELETE FROM public.cart_items WHERE user_id=auth.uid(); RETURN oid; END $$;
CREATE FUNCTION public.merge_guest_cart(_items jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb; pid uuid; chosen text; qty integer; existing uuid; BEGIN IF NOT public.is_account_active() THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items)>100 THEN RAISE EXCEPTION 'Invalid cart'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); FOR item IN SELECT * FROM jsonb_array_elements(_items) LOOP pid=(item->>'product_id')::uuid; chosen=nullif(item->>'size',''); qty=(item->>'quantity')::integer; IF qty IS NULL OR qty<1 OR qty>999 THEN RAISE EXCEPTION 'Invalid quantity'; END IF; IF NOT EXISTS(SELECT 1 FROM public.products WHERE id=pid AND is_active AND (cardinality(sizes)=0 OR sizes IS NULL OR chosen=ANY(sizes))) THEN RAISE EXCEPTION 'Unavailable product or size'; END IF; SELECT id INTO existing FROM public.cart_items WHERE user_id=auth.uid() AND product_id=pid AND size IS NOT DISTINCT FROM chosen LIMIT 1; IF existing IS NULL THEN INSERT INTO public.cart_items(user_id,product_id,size,quantity) VALUES(auth.uid(),pid,chosen,qty); ELSE UPDATE public.cart_items SET quantity=least(999,quantity+qty) WHERE id=existing; END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.merge_guest_cart(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.merge_guest_cart(jsonb) TO authenticated;